                while(ItemToRemove != LinkedList[CurrentPointer][0] and CurrentPointer != -1):
                         PreviousNode = CurrentPointer
                         CurrentPointer = LinkedList[CurrentPointer][1]
                if ItemToRemove == LinkedList[CurrentPointer][0]:
